public class Main {
    static class Parent {
        static int value = init("Parent");
        static int init(String name) {
            System.out.println(name + " <clinit>");
            return 42;
        }
    }

    static class Child extends Parent {
        static int childValue = init("Child");
    }

    static class Lazy {
        static {
            System.out.println("Lazy <clinit>");
        }
    }

    static class ConstantHolder {
        static final String TEXT = "compile-time";
        static final Integer BOXED = 1;
        static {
            System.out.println("ConstantHolder <clinit>");
        }
    }

    public static void main(String[] args) throws Exception {
        System.out.println("String loader: " + String.class.getClassLoader());
        System.out.println("Main loader: " + Main.class.getClassLoader().getName());

        Class<?> lazy = Main.class.getClassLoader().loadClass("Main$Lazy");
        System.out.println("loaded without init: " + lazy.getName());
        System.out.println("Class.forName triggers:");
        Class.forName("Main$Lazy");

        System.out.println("parent via child: " + Child.value);
        Child[] children = new Child[1];
        System.out.println("array length: " + children.length);
        System.out.println("compile constant: " + ConstantHolder.TEXT);
        System.out.println("boxed constant triggers: " + ConstantHolder.BOXED);
        System.out.println("child field: " + Child.childValue);

        assert lazy == Lazy.class;
        assert Child.childValue == 42;
    }
}
